  'Ingredients': '재료',
  'Sale proceeds do not cover crafting fees plus the live market value of consumed resources, ingredients and the bulk permit.': '판매 수익이 제작비와 소모할 자원, 아이템 재료 및 묶음 허가증의 실시간 시장 가치를 충당하지 못합니다.',
  'Goodwill improves your shared relationship score for all starting federations.': '우호 물자를 보내면 모든 시작 연방에 공통으로 적용되는 관계 점수가 오릅니다.',
  'A goodwill shipment reached Aurora Concord. Relations improved.': '친선 물자가 오로라 협약에 도착했습니다. 우호도가 올랐습니다.',
  'A goodwill shipment reached Azure Maritime League. Relations improved.': '친선 물자가 아주르 해양 연맹에 도착했습니다. 우호도가 올랐습니다.',
  'A goodwill shipment reached Solaris Commonwealth. Relations improved.': '친선 물자가 솔라리스 공동체에 도착했습니다. 우호도가 올랐습니다.',
  'A goodwill shipment reached Silverpeak Assembly. Relations improved.': '친선 물자가 실버피크 의회에 도착했습니다. 우호도가 올랐습니다.',
  'Origin story': '기원 이야기',
  'When the Long Frost silenced the forest roads, five villages kept a single greenhouse alive by sharing their last firewood. Its first spring sapling became the Union’s emblem. Their oldest promise is simple: no settlement faces winter alone.': '긴 혹한으로 숲길이 끊겼을 때, 다섯 마을은 마지막 장작을 나누어 온실 하나를 지켜 냈습니다. 그곳에서 봄에 처음 자란 묘목은 연합의 문장이 되었습니다. 가장 오래된 약속은 단순합니다. 어느 정착지도 홀로 겨울을 맞지 않는다는 것입니다.',
  'A storm scattered the northern observatories until a young keeper answered a distant light with a polished mirror. That chain of signals reunited the valleys. The Concord still keeps a lantern burning for discoveries that have not yet found their way home.': '폭풍으로 북쪽 관측소들이 고립되었을 때, 젊은 관리인이 닦아 낸 거울로 먼 불빛에 응답했습니다. 이어지는 신호가 계곡들을 다시 연결했습니다. 협약은 아직 돌아올 길을 찾지 못한 발견들을 위해 지금도 등불을 밝힙니다.',
  'Three rival harbors once argued over a vanished lighthouse. When their ships returned together through the same fog, the captains built a new beacon on neutral ground. The League was born around its flame: many shores, but safe passage for all.': '서로 경쟁하던 세 항구는 사라진 등대를 두고 다투었습니다. 같은 안개 속에서 배들이 함께 돌아오자, 선장들은 중립 지대에 새로운 봉화를 세웠습니다. 그 불꽃 곁에서 연맹이 태어났습니다. 해안은 여럿이어도 안전한 항로는 모두의 것이라는 뜻입니다.',
  'The first solar tower rose from a broken quarry, assembled by workers who were told the basin could never support a town. At dawn its mirrors lit every unfinished roof. The Commonwealth remembers that morning whenever a new settlement raises its first home.': '분지에는 마을이 들어설 수 없다는 말을 듣던 일꾼들이 버려진 채석장에 첫 태양탑을 세웠습니다. 새벽이 오자 거울들이 미완성 지붕 하나하나를 비추었습니다. 공동체는 새 정착지의 첫 집이 올라설 때마다 그 아침을 기억합니다.',
  'After an avalanche buried the mountain pass, miners, shepherds and mapmakers cut a new route from opposite sides. They met beneath the summit and carved their agreement into the stone. The Assembly’s shield honors the road no single village could have built.': '눈사태가 고갯길을 묻어 버리자 광부와 목동, 지도 제작자들이 양쪽에서 새 길을 냈습니다. 정상 아래에서 만난 이들은 바위에 약속을 새겼습니다. 의회의 방패는 어느 한 마을만으로는 만들 수 없었던 그 길을 기립니다.',
  'Choose any starting federation below. One membership at a time.': '아래 시작 연방 중 하나를 선택하세요. 한 번에 한 연방에만 가입할 수 있습니다.',
  'Contribute to your federation’s common vault.': '가입한 연방의 공동 금고에 기여하세요.',
  'Recruitment +25% per level · 20% population cap': '레벨당 모집 +25% · 인구의 20% 한도',
  'Recruitment starts at 5% of population, minimum one resident. Housing and climate bonuses cannot exceed a final 20% batch, rounded up. Paid arrivals remain unchanged.': '기본 모집 인원은 인구의 5%이며 최소 1명입니다. 주거와 기후 보너스를 포함해도 최종 모집 인원은 인구의 20%를 올림한 수를 넘지 않습니다. 이미 결제한 모집 인원은 유지됩니다.',
  'Open Inventory to manage items, craft supplies and enhance permanent fee-saving equipment.': '보관함에서 아이템을 관리하고 물자를 제작하며 영구 수수료 할인 장비를 강화하세요.',
