  'This wallet already owns another World fund. Your funded guest account is retained; use another wallet or restore the existing World fund in a separate browser session.': '이 지갑에는 이미 다른 월드 자금 계정이 있습니다. 게스트 자금은 그대로 유지됩니다. 다른 지갑을 사용하거나 별도 브라우저 세션에서 기존 월드 자금을 복구하세요.',
