  'Ethereum block changed during reserve verification.': '준비금 확인 중 이더리움 블록이 변경되었습니다.',
  'Origin holdings no longer cover pending allocations; automatic funding is blocked.': '원본 지갑 잔액이 대기 중인 배분을 뒷받침하지 못해 자동 공급이 차단되었습니다.',
  'Actual reserve holdings no longer cover confirmed obligations.': '실제 준비금 지갑 잔액이 확정된 지급 의무를 뒷받침하지 못합니다.',
  'Liquidity deficit does not map exactly to FTHG base units.': '유동성 부족분을 FTHG 최소 단위로 정확히 환산할 수 없습니다.',
