  'Market liquidity funded from existing assets and FTH$.': '기존 자산과 FTH$로 거래소 유동성을 제공했습니다.',
  'Dollar wallet authorized for gameplay.': '달러 지갑의 게임 사용을 승인했습니다.',
  'Wallet authorization failed.': '지갑 승인을 완료하지 못했습니다.',
  'Connect a wallet first.': '먼저 지갑을 연결하세요.',
  'Wallet returned an invalid signature.': '지갑이 올바르지 않은 서명을 반환했습니다.',
  'FTH$ issuance is closed, including bridge conversion and staking rewards. Trades move existing balances; gameplay payments move to the system treasury without changing supply. Market pools start empty and require donations of existing FTH$ and owned assets.': '브리지 전환과 스테이킹 보상을 포함한 FTH$ 신규 발행은 중단되었습니다. 거래는 기존 잔액을 옮기고 게임 비용은 공급량을 바꾸지 않고 시스템 금고로 이동합니다. 시장 풀은 비어 있는 상태로 시작하며 기존 FTH$와 보유 자산의 기부로 유동성을 공급해야 합니다.',
  'Open Wallet and staking for the real Ethereum FTHG bridge and staking contract. Authorize your Dollar wallet in Account before spending its FTH$ on gameplay. FTH$ displays at most two decimals; gameplay retains four-place accounting precision.': '지갑과 스테이킹에서 실제 이더리움 FTHG 브리지와 스테이킹을 사용하세요. 게임에서 FTH$를 사용하기 전에 계정에서 달러 지갑을 승인하세요. FTH$는 소수 둘째 자리까지 표시되며 게임 회계는 소수 넷째 자리까지 유지합니다.',
