  'Your World username and avatar are shared with Play. Edit them in the wallet profile menu.': '월드 사용자 이름과 아바타를 플레이에서도 사용합니다. 지갑 프로필 메뉴에서 편집하세요.',
  'Use World profile in Play': '플레이에서 월드 프로필 사용',
