  'Set your nickname in the avatar menu to join chat.': '아바타 메뉴에서 닉네임을 설정하면 채팅에 참여할 수 있어요.',
  'Your nickname is visible in settlement contacts and chat.': '설정한 닉네임은 정착지 연락처와 채팅에 표시됩니다.',
  'Nickname saved.': '닉네임을 저장했습니다.',
  'Public channel': '공개 채널',
  'Close': '닫기',
  'Invalid chat query.': '채팅 요청 주소가 올바르지 않습니다.',
  'Inbox lists public Explore chats within your current exploration radius and public chats for the federations represented there. Contacts is under the avatar menu. Visit a settlement to join its separate visitor group chat; these rooms are not listed in Inbox. Chat keeps the latest 100 messages per room with one message every three seconds. Choose a unique nickname and never share secrets.': '메시지함에는 현재 탐험 시야 안의 탐험 공개 채팅과 해당 정착지가 속한 연방의 공개 채팅이 표시됩니다. 연락처는 아바타 메뉴에 있습니다. 정착지를 방문하면 별도의 방문자 단체 채팅에 참여할 수 있으며 이 채팅은 메시지함에 표시되지 않습니다. 채팅방마다 최근 메시지 100개를 보관하고 3초마다 1개를 보낼 수 있습니다. 고유 닉네임을 설정하고 민감한 정보는 공유하지 마세요.',
  'Contacts': '연락처',
  'Nearby settlements': '주변 정착지',
  'Unnamed settlement': '이름 없는 정착지',
  'Public chat': '공개 채팅',
