  'Average price · FTHG': '평균 체결가 · FTHG',
  'Compare prices in the grid or table, filter your holdings, and choose Buy or Sell to prepare an order. Review the amount and total before confirming; selecting a price never places an order.': '카드나 표에서 가격을 비교하고 보유 품목만 골라볼 수 있어요. 구매·판매를 선택해 주문을 준비한 뒤 수량과 총액을 확인하세요. 가격을 선택하는 것만으로 주문이 접수되지는 않습니다.',
  'Featheral | White paper': 'Featheral | 백서',
  'Learn about Featheral game rules, the simulated economy, governance and prototype limitations.': 'Featheral의 게임 규칙, 가상 경제, 거버넌스와 프로토타입의 한계를 알아보세요.',
  'Explore the white paper': '백서 살펴보기',
