  'Layout controls': '배치 조작 안내',
  'Move any owned building or decoration to an empty land cell. Moving is free and does not change production or building effects.': '보유한 건물과 장식을 빈 땅으로 자유롭게 옮겨 보세요. 이동 비용은 없으며, 생산량과 건물 효과도 그대로 유지됩니다.',
  'In Layout, drag a building onto an empty land cell, or select Move on map and tap a destination. Drag empty ground to pan. Use coordinates for precise placement. Buildings cannot be demolished; decorations can return to inventory.': '배치·꾸미기에서 건물을 빈 땅으로 드래그하거나, 지도에서 옮기기를 누른 뒤 원하는 칸을 선택하세요. 빈 땅을 드래그하면 지도를 움직일 수 있고, 좌표로도 배치할 수 있습니다. 건물은 철거할 수 없으며, 장식은 인벤토리로 회수할 수 있습니다.',
  'This is your settlement parcel, not unexplored world territory. Rearranging never discovers resources or changes exploration.': '이 화면은 정착지 내부 부지이며, 아직 탐험하지 않은 월드 지역이 아닙니다. 건물을 옮겨도 자원이 발견되거나 탐험 진행도가 바뀌지 않습니다.',
  'Settlement grid. Drag to pan, scroll to zoom. Select a building to manage it. In Layout, drag buildings or choose a land cell to move them. Arrow keys move the cursor; Enter selects.': '정착지 격자 지도. 드래그로 이동하고 스크롤로 확대·축소하세요. 건물을 선택하면 관리 창이 열립니다. 배치·꾸미기에서는 건물을 드래그하거나 빈 땅을 선택해 옮길 수 있습니다. 방향키로 칸을 선택하고 Enter로 확인하세요.',
  'Open Layout to manage buildings and decorations.': '배치·꾸미기 메뉴에서 건물과 장식을 관리하세요.',
  'Establish a settlement before arranging buildings.': '정착지를 먼저 세운 뒤 건물을 배치하세요.',
  'You do not own this settlement building or decoration.': '보유하지 않은 건물이나 장식은 배치할 수 없습니다.',
  'Buildings cannot be removed. Move them to another cell.': '건물은 철거할 수 없습니다. 다른 칸으로 옮겨 주세요.',
  'Choose a land cell inside the settlement boundary.': '정착지 경계 안의 땅을 선택해 주세요.',
  'That cell is occupied. Choose an empty cell.': '이미 다른 건물이나 장식이 있는 칸입니다. 빈 칸을 선택해 주세요.',
  'Could not load settlement decoration artwork.': '정착지 장식 이미지를 불러오지 못했습니다.',
