  'A quiet clearing today. A place full of life tomorrow.': '작은 공터에서 시작해, 주민들의 일상이 모이는 곳으로.',
  'Gather around the square. Make every corner feel like home.': '광장에 모여드는 이웃들. 골목마다 나만의 취향을 더해 보세요.',
  'A city of busy streets and little places to call your own.': '활기찬 거리와 아늑한 쉼터. 나만의 도시를 완성해 보세요.',
  'Illustrated settlement streets': '정착지 거리 전경',
