  'Decorate your settlement': '정착지 꾸미기',
  'Select a space, then place an owned decoration. Move or remove it freely; your items are never consumed.': '꾸밀 공간을 고르고 보유한 장식 아이템을 배치하세요. 자유롭게 옮기거나 회수할 수 있고, 아이템은 소모되지 않습니다.',
