  'Make your first decoration in the workshop.': '제작 공방에서 첫 장식 아이템을 만들어 보세요.',
  'Craft decorations': '장식 아이템 제작',
  'Decorations are cosmetic only. Placed items keep their inventory slot. Replacing a decoration does not destroy either item.': '장식은 외형만 바꾸며 생산량에는 영향을 주지 않습니다. 배치한 아이템도 인벤토리 1칸을 차지합니다. 다른 장식으로 바꿔도 기존 아이템은 사라지지 않습니다.',
  'Equipment, decorations and collectibles use item slots. Raw resources stay separate. Equipped and placed items still use one slot each.': '인벤토리에는 장비·장식 아이템·수집품을 보관합니다. 원자재는 별도이며, 장착하거나 배치한 아이템도 각각 1칸을 차지합니다.',
  'Establish a settlement before decorating.': '정착지를 먼저 세운 뒤 꾸미기를 시작하세요.',
  'No decoration is placed in this space.': '이 공간에 배치된 장식이 없습니다.',
  'Craft this decoration before placing it.': '장식 아이템을 먼저 제작한 뒤 배치하세요.',
