  'Procedural world. Click unknown nearby terrain to send a week-long expedition with two residents. Travel on known terrain with arrow keys. Drag to pan and scroll to zoom.': '자동 생성되는 월드입니다. 주변의 미탐험 지역을 선택하면 주민 2명이 탐험을 떠납니다. 탐험에는 최소 게임 시간 1주가 걸립니다. 탐험한 지역은 방향키로 이동하고, 드래그와 스크롤로 지도를 이동하거나 확대·축소하세요.',
