  'Minimap showing explored terrain and nearby silhouettes fading into fog. Fogged previews are not explored.': '탐험한 지형과 주변 지형의 윤곽을 보여 주는 미니맵입니다. 미탐험 지역은 멀수록 안개에 가려집니다. 안개 너머로 보이는 지역도 탐험을 완료해야 이용할 수 있습니다.',
