  'Your settlement has reached the highest settlement tier.': '정착지가 최고 단계에 도달했습니다.',
  'Oil fuel per resident per game day: Town 0.001 bbl, District 0.002, City 0.004, Metropolis 0.008, Capital 0.016, Regional Hub 0.024, Urban Center 0.032, Metropolitan Region 0.040, World City 0.048, Global City 0.064, Megacity 0.128, Great Megacity 0.256. Demand is not climate-adjusted.': '주민 1인당 게임 하루 석유 소비량: 소도시 0.001 bbl, 도시 구역 0.002, 도시 0.004, 대도시 0.008, 수도 0.016, 광역 거점 0.024, 도시 중심지 0.032, 광역 도시권 0.040, 국제 도시 0.048, 세계 도시 0.064, 메가시티 0.128, 초대형 메가시티 0.256. 기후에 따른 변동은 없습니다.',
