  'Recruitment progress': '주민 모집 진행도',
  'Pay metal upfront. Residents arrive after one game week. One batch at a time; no automatic repeat.': '금속을 먼저 지불하면 게임 시간 1주 뒤에 주민이 합류합니다. 한 번에 한 팀만 모집하며 자동으로 반복하지 않습니다.',
  'Recruit residents in Settlement. Offline time never banks extra batches.': '정착지에서 주민을 모집하세요. 오프라인 동안 모집 횟수는 누적되지 않습니다.',
  'Includes your settlement and fellow federation members.': '내 정착지와 같은 연방에 속한 정착지의 주민을 포함합니다.',
  'Join or found a federation to see its population.': '연방에 가입하거나 연방을 창설하면 연방 인구를 확인할 수 있습니다.',
  'Server settlements only, including inactive settlements. Simulated neighbors are excluded.': '활동하지 않는 정착지를 포함한 서버 정착지의 인구입니다. 가상의 이웃은 제외합니다.',
  'Invite residents': '주민 모집',
  'Invite residents, server sync required': '주민 모집: 서버 동기화 필요',
  'Awaiting server confirmation': '서버 확인 대기 중',
  'Confirming': '확인 중',
  'Settlement required.': '먼저 정착지를 세우세요.',
  'Assign residents to a discovered site in Settlement. Oil and lithium also require a city bank.': '정착지에서 발견한 자원지에 주민을 배치하세요. 석유·리튬 채집에는 도시 은행이 필요합니다.',
  'Storage full. Weekly overflow is discarded. Claim or upgrade.': '창고가 가득 찼습니다. 초과 생산분은 사라집니다. 자원을 받거나 창고를 업그레이드하세요.',
  'Active crew delivers once per in-game week. Claim at 50%.': '채집팀이 게임 시간 1주마다 자원을 보냅니다. 저장 공간이 50% 이상 차면 받을 수 있습니다.',
  'Owned': '보유량',
  'Water facilities': '급수 시설',
  'Well': '우물',
  'Rain collector': '빗물 집수 시설',
  'Pumping station': '양수장',
  'Water output': '물 채집량',
  'Water per resident / week': '주민 1명당 주간 물 채집량',
  'Next work week': '다음 작업 주부터',
  'Facility bonuses add together and increase Water collected per resident. They require assigned Water crews and apply from the next work week, without changing paid deliveries. Expand storage to keep the extra output. No extra weekly upkeep.': '시설 보너스는 합산되어 주민 1명당 물 채집량을 늘립니다. 물 채집팀이 필요하며 진행 중인 채집량은 바뀌지 않고 다음 작업 주부터 적용됩니다. 늘어난 채집량을 저장할 수 있도록 창고도 확장하세요. 시설 자체의 주간 유지비는 없습니다.',
  'Establish a settlement before constructing Water facilities.': '정착지를 세운 뒤 급수 시설을 건설할 수 있습니다.',
  'Collection': '채집',
  'Consumption (transport)': '소모 (운송)',
  'Consumption (population)': '소모 (주민)',
  'Weekly Water': '주간 물 소비',
  'Weekly departures at risk': '주간 이탈 위험 인원',
  'Last weekly departures': '지난주 이탈 인원',
  'Next consumption': '다음 소비까지',
  'Buy Water': '물 구매',
  'Each resident consumes 105 Water per game week from owned stock only. Claim or buy Water before the deadline. Pending Water is not consumed automatically. Auto prioritizes Water before growth and surplus gathering. On shortage, 5% of unsupported residents leave each week, rounded up, including offline; population can reach zero. Departures reduce crews or cancel expeditions when survivors cannot staff them. Recruitment remains available.': '주민 1명당 게임 시간 1주에 보유한 물 105개를 소비합니다. 기한 전에 물을 수령하거나 구매하세요. 수령 대기 중인 물은 자동으로 소비되지 않습니다. 자동 배치는 성장과 추가 채집보다 물 확보를 우선합니다. 물이 부족하면 공급받지 못한 주민의 5%가 매주 이탈하며 소수점은 올림합니다. 오프라인에도 적용되며 인구가 0명이 될 수 있습니다. 남은 주민이 부족하면 채집 인원이 줄거나 탐험이 취소됩니다. 주민 모집으로 다시 인구를 늘릴 수 있습니다.',
  'Storage full': '창고 가득 참',
  'Pending / cap': '수령 대기 / 저장 한도',
  'Claim at 50%': '50%부터 받기',
  'Production': '자원 관리',
  'Warehouse': '창고',
  'Active residents': '주민 배치',
  'Crews deliver every 7 world days. No assigned residents = no production. First week is locked; later reassignment forfeits unfinished work. Yields are fixed when assigned.': '주민을 배치하면 게임 시간 7일마다 채집한 자원이 도착합니다. 미배치 주민은 자원을 생산하지 않습니다. 첫 1주는 배치를 해제하거나 변경할 수 없습니다. 이후 재배치하면 진행 중인 채집은 취소되며, 채집량은 배치 시 확정됩니다.',
  'No crew': '미배치',
  'Discovered site': '발견한 자원지',
  'Explore to find a site': '탐험해서 자원지를 발견하세요',
  'Assign': '배치',
  'Next delivery:': '다음 자원 도착까지:',
  '. Set residents to 0 to release after the first week.': '. 첫 1주가 지난 뒤 주민 수를 0으로 설정하면 배치를 해제할 수 있습니다.',
  'Discover a site and build a city bank.': '자원지를 발견하고 도시 은행을 건설하세요.',
  'Choose residents and a site to start a full week of work.': '주민 수와 자원지를 선택하면 채집이 시작됩니다. 첫 자원은 게임 시간 1주 후 도착합니다.',
  'Expedition team available': '탐험대 편성 가능',
  'Returns in': '탐험대 복귀까지',
  'Click unknown nearby terrain, or use Explore. Two available residents survey for 1–3 weeks, then return. Travel through known tiles is instant and does not reveal more land.': '주변의 미탐험 지역을 선택하거나 탐험 버튼을 누르세요. 미배치 주민 2명이 게임 시간 1~3주 동안 탐험한 뒤 복귀합니다. 탐험한 지역은 즉시 이동할 수 있지만, 이동만으로 새 지역이 열리지는 않습니다.',
