  'Build more. Unlock more.': '성장할수록 새로운 기능이 열려요.',
  'Expand your warehouse to store more. Build a city bank to unlock oil and lithium gathering and trading. Join a federation and build a town hall to try simulated voting.': '창고를 확장해 더 많이 저장하고, 도시 은행을 건설해 석유·리튬 채집과 거래를 해금하세요. 연방에 가입하고 마을 회관을 갖추면 가상 안건에 투표할 수 있습니다.',
