  'Metal is a gameplay resource; FTHG is the marketplace currency. Exchange them at floating in-game rates. Neither is an on-chain token or redeemable for cash. No investment returns or governance rights are promised.': '금속은 성장에 쓰는 자원이고, FTHG는 거래소에서 쓰는 재화입니다. 게임 내 변동 시세로 서로 교환할 수 있습니다. 둘 다 온체인 토큰이 아니며 현금화할 수 없습니다. 투자 수익이나 거버넌스 권리를 약속하지 않습니다.',
