  'Curiosity looks': '궁금한 점이',
  'good on you.': '있으신가요?',
  'Go deeper: white paper (.md)': '더 알아보기: 백서 (.md)',
  'What is Featheral?': 'Featheral은 어떤 게임인가요?',
  'Featheral is a casual browser-based world-building and Web3 governance simulation. Explore a map, grow a settlement, manage time-based resources, and experiment with a simulated federation and assembly. It is currently a single-player prototype backed by a mock server, not a deployed DAO.': 'Featheral은 브라우저에서 즐기는 캐주얼 정착지 건설·Web3 거버넌스 시뮬레이션입니다. 지도를 탐험하고 정착지를 키우며, 주민을 배치해 자원을 모으고 가상의 연방과 의회에 참여할 수 있습니다. 현재는 시뮬레이션 서버 기반 싱글플레이 프로토타입이며, 실제 배포된 DAO가 아닙니다.',
  'Do I need a wallet or any crypto?': '지갑이나 암호화폐가 필요한가요?',
  'No. Start directly in your browser without a wallet, payment, gas fee or token claim. Earn in-game FTHG by selling Metal or other assets; use it only in the marketplace.': '아니요. 지갑 연결, 결제, 가스비, 토큰 클레임 없이 브라우저에서 바로 플레이하세요. 금속이나 다른 자산을 팔아 게임 내 FTHG를 얻고 거래소에서 사용하세요.',
  'How do resources and progress work?': '자원을 모으고 성장하려면 어떻게 하나요?',
  'Will my little world be saved?': '내 세계는 저장되나요?',
  'The mock server saves progress for your anonymous browser session. Keep using the same browser and hostname. The session cookie lasts seven real days; losing or expiring it loses access, and recovery is not available in this prototype. Exports are informational, not importable balances.': '시뮬레이션 서버가 익명 브라우저 세션에 진행 상황을 저장합니다. 같은 브라우저와 사이트 주소로 접속하세요. 세션 쿠키는 실제 7일간 유효합니다. 쿠키가 삭제되거나 만료되면 내 월드에 접근할 수 없으며, 현재 프로토타입에는 복구 기능이 없습니다. 내보낸 스냅샷은 확인용으로, 자원 복원에 사용할 수 없습니다.',
  'Is Feather Gold (FTHG) live?': 'Feather Gold(FTHG)는 출시되었나요?',
  'FTHG is available as an off-chain game currency, with floating Metal exchange in the marketplace. No on-chain token, sale, airdrop or cash redemption exists. The zero address is only a placeholder; never send assets to it.': 'FTHG는 게임 내 오프체인 재화로 사용할 수 있으며, 거래소에서 금속과 변동 시세로 교환할 수 있습니다. 온체인 토큰 배포, 토큰 세일, 에어드롭, 현금 출금은 지원하지 않습니다. 제로 주소는 예시이므로 자산을 절대 전송하지 마세요.',
  'How can I join in or hear about updates?': '어떻게 참여하고 소식을 받을 수 있나요?',
  'Official GitHub, Discord, X, and Telegram links have not been published yet. Their cards are clearly marked Coming soon. Once verified links are added, use those channels to follow announcements or participate. No email list, automatic notification enrollment, or third-party account connection is active here.': '공식 GitHub, Discord, X, Telegram 링크는 아직 공개되지 않았으며 각 카드에 준비 중으로 표시되어 있습니다. 검증된 링크가 추가되면 해당 채널에서 공지를 확인하고 참여하세요. 이메일 목록, 자동 알림 등록, 외부 계정 연결 기능은 운영하지 않습니다.',
  'READY TO BUILD? START NOW.': '설치 없이 지금 시작하세요',
  'Build your first settlement today.': '첫 정착지를 지금 세우세요.',
  'Start playing free': '무료로 플레이 시작',
