  'FTHG and Metal are in-game balances, not deployed tokens. No cash withdrawals.': 'FTHG와 금속은 게임 내 재화이며 배포된 토큰이 아닙니다. 현금 출금은 지원하지 않습니다.',
  'Live total unavailable': '실시간 통계를 확인할 수 없습니다',
