  'Featheral | A little world. A bigger say.': 'Featheral | 작은 세계, 더 큰 목소리.',
  'Explore 21 terrain types, assign residents to gather resources, and grow a settlement into a capital. Play Featheral free in your browser. No install, wallet connection, or purchase.': '21가지 지형을 탐험하고 주민을 배치해 자원을 모으세요. 정착지를 수도까지 키우는 무료 싱글플레이 게임 Featheral. 설치·지갑 연결·결제 없이 브라우저에서 지금 시작하세요.',
  'Build your first settlement, put residents to work, and unlock new buildings. Start this free single-player browser game now.': '첫 정착지를 세우고 주민을 배치해 새로운 건물을 해금하세요. 무료 싱글플레이 브라우저 게임, 지금 시작하세요.',
  'Your first settlement. Your next expedition. Your future capital. Play free in your browser, with no wallet connection or purchase.': '첫 정착지부터 다음 탐험, 나만의 수도까지. 지갑 연결·결제 없이 브라우저에서 무료로 플레이하세요.',
  'Play the Featheral world-building and governance simulator. Explore, settle, and grow a community. No wallet or purchase required.': 'Featheral에서 지형을 탐험하고 자원을 모아 정착지를 키워 보세요. 지갑 연결·결제 없이 즐기는 한국어 정착지 건설·거버넌스 시뮬레이션입니다.',
  'Featheral: A little world. A bigger say. An illustrated settlement surrounded by trees.': 'Featheral: 작은 세계, 더 큰 목소리. 나무로 둘러싸인 정착지의 일러스트.',
